examples.template:
MonarchAiPromptInput(
    {{label}},
    text: $prompt,
    toolbar: {
        MonarchAiPromptToolbar {
            Toggle({{toggle}}, systemImage: "magnifyingglass", isOn: $searchesWeb)
            Button({{button}}, systemImage: "list.bullet") {}
        }
    },
    onSubmit: { _ in }
)

examples.code:
MonarchAiPromptInput(
    "Message the assistant",
    text: $prompt,
    toolbar: {
        MonarchAiPromptToolbar {
            Toggle("Search the web", systemImage: "magnifyingglass", isOn: $searchesWeb)
            Button("Templates", systemImage: "list.bullet") {}
        }
    },
    onSubmit: { _ in }
)
